const BASE = import.meta.env.VITE_API_BASE_URL || '';
async function api(path, { token, body, signal, method, retried = false } = {}) {
  // Admin data is authenticated and frequently refreshed. Avoid browser conditional
  // requests (304) replaying a cached CORS header from a different dev-server port.
  const res = await fetch(`${BASE}/api/v1${path}`, { signal, cache: 'no-store', method: method || (body ? 'POST' : 'GET'), headers: { ...(body ? { 'Content-Type': 'application/json' } : {}), ...(token ? { Authorization: `Bearer ${token}` } : {}) }, ...(body ? { body: JSON.stringify(body) } : {}) });
  if(res.status===401&&token&&!retried&&readSession()) {
    const current=readSession();
    const renewed=current.accessToken!==token?current:await refreshSession();
    return api(path,{token:renewed.accessToken,body,signal,method,retried:true});
  }
  const result = await res.json();
  if (!res.ok) { const error = new Error(result.error?.message || 'Request failed'); error.status = res.status; throw error; }
  return result.data;
}
