const routeFromPath = pathname => {
  const path=pathname.replace(/\/$/,'')||'/';
  const userMatch=path.match(/^\/admin\/users\/([^/]+)(\/steps)?$/);
  if(userMatch){const userId=decodeURIComponent(userMatch[1]);return {tab:'users',userId,stepUser:userMatch[2]?userId:null};}
  const partnerMatch=path.match(/^\/admin\/partners\/([^/]+)$/);
  if(partnerMatch)return {tab:'partners',partnerId:decodeURIComponent(partnerMatch[1]),userId:null,stepUser:null};
  const pageMatch=path.match(/^\/admin\/([^/]+)$/);
  const tab=pageMatch?.[1]||'overview';
  return {tab:tabs.some(item=>item.id===tab)?tab:'overview',partnerId:null,userId:null,stepUser:null};
};
const routeForTab = tab => tab==='overview'?'/admin/overview':`/admin/${tab}`;
