 const readable=key=>key.replace(/([a-z])([A-Z])/g,'$1 $2').replaceAll('_',' ');
 return <Modal className="detail-modal record-dialog" labelledBy="record-title" onClose={onClose}><div className="record-sticky-header"><div className="panel-heading"><div><span className="eyebrow">RECORD DETAILS</span><h2 id="record-title">{user?.name || 'User record'}</h2><p>{user?.email || `User ID: ${record.userId || '—'}`}</p>{user?.publicId && <small className="public-user-id">{user.publicId}</small>}</div><Button autoFocus className="secondary" onClick={onClose}>Close</Button></div><div className="record-context"><span className="badge">{label(record.metricType || record.deviceType)}</span><strong>{record.value!==undefined?`${record.value} ${record.unit || ''}`:record.model}</strong>{record.recordedAt&&<span>{format(record.recordedAt)}</span>}</div></div><dl>{Object.entries(record).filter(([key])=>key!=='user').map(([key,value])=><React.Fragment key={key}><dt>{readable(key)}</dt><dd>{typeof value==='object'&&value!==null?JSON.stringify(value,null,2):String(value??'—')}</dd></React.Fragment>)}</dl></Modal>;
