  const [section,setSection] = useState('records'); const [page,setPage] = useState(1); const [limit,setLimit] = useState(20);
  const [q,setQ] = useState(''); const [metric,setMetric] = useState(''); const [from,setFrom] = useState(''); const [to,setTo] = useState('');
  const [result,setResult] = useState(null); const [loading,setLoading] = useState(true); const [error,setError] = useState('');
  const [confirm,setConfirm] = useState(false); const [saving,setSaving] = useState(false); const [version,setVersion] = useState(0);
